#!/usr/bin/env python3
"""Runs the encoder conformance cases (generated by enc.test.mjs) in Unicorn's ARM64 emulation.

Each case is a short program plus the register/memory state before it runs and the state it must
produce. Every general register is compared (so stray clobbers are caught), plus the floating-point
registers and memory words the case declares.
"""
import json
import sys

from unicorn import Uc, UC_ARCH_ARM64, UC_MODE_ARM, UC_HOOK_CODE
from unicorn.arm64_const import (
    UC_ARM64_REG_X0, UC_ARM64_REG_SP, UC_ARM64_REG_D0, UC_ARM64_REG_Q0,
)

STACK = 0x600000
MB = 1 << 20


def isnan_bits(bits):
    return ((bits >> 52) & 0x7FF) == 0x7FF and (bits & ((1 << 52) - 1)) != 0


def isnan32_bits(bits):
    return ((bits >> 23) & 0xFF) == 0xFF and (bits & ((1 << 23) - 1)) != 0


def u64(v):
    return v & ((1 << 64) - 1)


def main(path):
    spec = json.load(open(path))
    code_addr = spec["codeAddr"]
    failures = []
    checks = 0

    total = len(spec["cases"])
    for index, case in enumerate(spec["cases"]):
        if index and index % 100 == 0:
            print(f"  ... {index}/{total}", file=sys.stderr)
        uc = Uc(UC_ARCH_ARM64, UC_MODE_ARM)
        uc.mem_map(code_addr, 4 * MB)
        uc.mem_map(code_addr + 4 * MB, 16 * MB)  # data
        uc.mem_map(0x10000000, 4 * MB)  # stack
        code = bytes.fromhex(case["code"])
        uc.mem_write(code_addr, code)
        for addr, hexbytes in case["mem"]:
            uc.mem_write(int(addr), bytes.fromhex(hexbytes))
        for name, value in case["regs"].items():
            uc.reg_write(UC_ARM64_REG_X0 + int(name[1:]), int(value))
        uc.reg_write(UC_ARM64_REG_SP, int(case["sp"]) if "sp" in case else 0x10000000 + 2 * MB)
        for name, bits in case["dregs"].items():
            uc.reg_write(UC_ARM64_REG_Q0 + int(name[1:]), int(bits))
        count = [0]

        def limit(uc_, address, size, _user):
            count[0] += 1
            if count[0] > 5000:
                uc_.emu_stop()

        uc.hook_add(UC_HOOK_CODE, limit)
        try:
            uc.emu_start(code_addr, code_addr + len(code))
        except Exception as err:  # noqa: BLE001 - reported per case
            failures.append(f"{case['name']}: emulation error {err}")
            continue
        if count[0] > 5000:
            failures.append(f"{case['name']}: program did not terminate")
            continue

        expects = case["expect"]
        for name, want in expects["regs"].items():
            checks += 1
            got = u64(uc.reg_read(UC_ARM64_REG_X0 + int(name[1:])))
            if got != int(want):
                failures.append(f"{case['name']}: {name} = 0x{got:x}, want 0x{int(want):x}")
        # Stray clobbers: registers not named in the inputs or the expectations must be untouched.
        declared = set(case["regs"]) | set(expects["regs"])
        for i in range(19):
            name = f"x{i}"
            if name in declared:
                continue
            checks += 1
            got = u64(uc.reg_read(UC_ARM64_REG_X0 + i))
            if got != 0:
                failures.append(f"{case['name']}: {name} clobbered (0x{got:x})")
        for name, bits in expects["dregs"].items():
            checks += 1
            got = uc.reg_read(UC_ARM64_REG_Q0 + int(name[1:]))
            want = int(bits)
            if got != want and not (isnan_bits(got) and isnan_bits(want)) and not (isnan32_bits(got) and isnan32_bits(want)):
                failures.append(f"{case['name']}: {name} = 0x{got:016x}, want 0x{want:016x}")
        for addr, hexbytes in expects["mem"]:
            checks += 1
            got = uc.mem_read(int(addr), len(hexbytes) // 2)
            if bytes(got) != bytes.fromhex(hexbytes):
                failures.append(f"{case['name']}: mem[0x{int(addr):x}] = {bytes(got).hex()}, want {hexbytes}")

    if failures:
        print(f"FAILURES ({len(failures)} of {checks} checks):")
        for f in failures[:60]:
            print("  " + f)
        sys.exit(1)
    print(f"ok: {checks} encoder checks passed in unicorn")


if __name__ == "__main__":
    main(sys.argv[1])
